mapper.sql:
pr.status = 'SUBMITTED'
AND EXISTS (
    SELECT 1
    FROM approver_department_scopes scope
    WHERE scope.user_id = #{criteria.approverId}
      AND scope.department_id = pr.department_id
)

    AND (
        pr.request_number ILIKE ('%' || #{criteria.keyword} || '%') ESCAPE '\'
        OR pr.title ILIKE ('%' || #{criteria.keyword} || '%') ESCAPE '\'
        OR applicant.display_name ILIKE ('%' || #{criteria.keyword} || '%') ESCAPE '\'
        OR EXISTS (
            SELECT 1
            FROM request_items searched_item
            WHERE searched_item.request_id = pr.id
              AND (
                  searched_item.product_name ILIKE ('%' || #{criteria.keyword} || '%') ESCAPE '\'
                  OR searched_item.model_number ILIKE ('%' || #{criteria.keyword} || '%') ESCAPE '\'
              )
        )
    )


    AND pr.submitted_at >= #{criteria.submittedFrom}


    AND pr.submitted_at < #{criteria.submittedToExclusive}


    AND pr.department_id = #{criteria.departmentId}


    AND pr.desired_delivery_date < #{criteria.desiredDeliveryDateBefore}
